"use strict";function query(n){$.ajax({url:_global.root+"applicants/index",dataType:"html",method:"POST",data:{jobTitle:$("#keyword").val()},beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#applicants-detail").html(n);floatThead("table#data")},error:function(){alert(_messages.errorTryAgain)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function deleteJobTitle(n){confirm("Are you sure you want to delete?",function(){$.post(_global.root+"applicants/Delete",{id:n},function(n){n.IsSuccessful?query(!1):alert(n.Message)}).error(function(){alert(_messages.errorTryAgain)})})}var canNotUpdate=function(n){$("#txtJobTile_"+n).val($("#spanJobTitle_"+n).text())};$(document).ready(function(){$("#keyword").keyup(function(n){n.keyCode===13&&query(!1)});$("#submit").on("click",function(){query(!1)});var n=getParam("query");n!=null&&$("#keyword").val(n);query(!0)});